CREATE POLICY "Authenticated can read activity images" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'activity-images');
CREATE POLICY "Users can upload own activity images" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'activity-images' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Users can update own activity images" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'activity-images' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Users can delete own activity images" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'activity-images' AND (storage.foldername(name))[1] = auth.uid()::text);